bfs.py:
from collections import deque
graph = {"A": ["B", "C"], "B": ["D"], "C": ["D"], "D": []}
dist = {"A": 0}
q = deque(["A"])
while q:
    node = q.popleft()
    for nxt in graph[node]:
        if nxt not in dist:
            dist[nxt] = dist[node] + 1
            q.append(nxt)
print(dist)

